#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long maximumTotalValue(std::vector<int>& values, int k) {
        std::sort(values.rbegin(), values.rend());
        long long sum = 0;
        int take = std::min((int)values.size(), k);
        for (int i = 0; i < take; ++i) sum += values[i];
        return sum;
    }
};

import java.util.*;

class Solution {
    public long maximumTotalValue(int[] values, int k) {
        Arrays.sort(values);
        long sum = 0;
        int n = values.length;
        int take = Math.min(n, k);
        for (int i = 0; i < take; i++) {
            sum += values[n - 1 - i];
        }
        return sum;
    }
}

